+  private final IntVector daysOfMonth;
+  private final IntVector monthsOfYear;
+  private final IntVector years;
+
+  private final DateTimeZone timeZone;
+
+  public PosixLtVector(ListVector x) {
+    this.vector = x;
+    seconds =
(IntVector)vector.getElementAsSEXP(x.getIndexByName(SECOND_FIELD));
+    minutes =
(IntVector)vector.getElementAsSEXP(x.getIndexByName(MINUTE_FIELD));
+    hours =
(IntVector)vector.getElementAsSEXP(x.getIndexByName(HOUR_FIELD));
+    monthsOfYear =
(IntVector)vector.getElementAsSEXP(x.getIndexByName(MONTH_FIELD));
+    daysOfMonth =
(IntVector)vector.getElementAsSEXP(x.getIndexByName(DAY_OF_MONTH_FIELD));
+    years =
(IntVector)vector.getElementAsSEXP(x.getIndexByName(YEAR_FIELD));
+
+    Vector tzoneAttribute = (Vector) vector.getAttribute(Symbols.TZONE);
+    if(tzoneAttribute.length() >= 1) {
+      timeZone =
Time.timeZoneFromRSpecification(tzoneAttribute.getElementAsString(0));
+    } else {
+      timeZone = DateTimeZone.getDefault();
+    }
+  }
+
+  @Override
+  public int length() {
+    return seconds.length();
+  }
+
+  @Override
+  public DateTime getElementAsDateTime(int index) {
+    return new DateTime(
+        years.getElementAsInt(index)+1900,
+        monthsOfYear.getElementAsInt(index)+1,
+        daysOfMonth.getElementAsInt(index),
+        hours.getElementAsInt(index),
+        minutes.getElementAsInt(index),
+        seconds.getElementAsInt(index),
+        timeZone);
+  }
+
+  public static class Builder {
+    private ListVector.Builder list = new ListVector.Builder(9);
+    private IntVector.Builder second = new IntVector.Builder();
+    private IntVector.Builder minute = new IntVector.Builder();
+    private IntVector.Builder hour = new IntVector.Builder();
+    private IntVector.Builder dayOfMonth = new IntVector.Builder();
+    private IntVector.Builder month = new IntVector.Builder();
+    private IntVector.Builder year = new IntVector.Builder();
+    private IntVector.Builder weekday = new IntVector.Builder();
+    private IntVector.Builder dayOfYear = new IntVector.Builder();
+    private IntVector.Builder dst = new IntVector.Builder();
+
+    public Builder add(DateTime time) {
+      second.add(time.getSecondOfMinute());
+      minute.add(time.getMinuteOfHour());
+      hour.add(time.getHourOfDay());
+      dayOfMonth.add(time.getDayOfMonth());
+      month.add(time.getMonthOfYear()-1);
+      year.add(time.getYear()-1900);
+      weekday.add(getRDayOfWeek(time));
+      dayOfYear.add(time.getDayOfYear()-1);
+      dst.add(getDstFlag(time));
+      return this;
+    }
+
+    public Builder addAll(Iterable<DateTime> dateTimes) {
+      for(DateTime dateTime : dateTimes) {
+        add(dateTime);
+      }
+      return this;
+    }
+
+    public Builder addNA() {
+      second.addNA();
+      minute.addNA();
+      hour.addNA();
+      dayOfMonth.addNA();
+      month.addNA();
+      year.addNA();
+      weekday.addNA();
+      dayOfYear.addNA();
+      dst.add(-1);
+      return this;
+    }
+
+    public Builder withTimeZone(DateTimeZone tz) {
+      list.setAttribute(Symbols.TZONE, new StringVector(tz.getID()));
+      return this;
+    }
+
+    private static int getDstFlag(DateTime time) {
+      if( time == null ) {
+        return -1;
+      } else {
+        return time.getZone().isStandardOffset(time.getMillis()) ? 0 : 1;
+      }
+    }
+
+    private static int getRDayOfWeek(DateTime time) {
+      if(time.getDayOfWeek()==7) {
+        return 0;
+      } else {
+        return time.getDayOfWeek();
+      }
+    }
+
+    public ListVector buildListVector() {
+      list.add(SECOND_FIELD, second);
+      list.add(MINUTE_FIELD, minute);
+      list.add(HOUR_FIELD, hour);
+      list.add(DAY_OF_MONTH_FIELD, dayOfMonth);
+      list.add(MONTH_FIELD, month);
+      list.add(YEAR_FIELD, year);
+      list.add(WEEKDAY_FIELD, weekday);
+      list.add(DAY_OF_YEAR_FIELD, dayOfYear);
+      list.add(DST_FIELD, dst);
+      list.setAttribute(Symbols.CLASS, new
StringVector("POSIXlt", "POSIXt"));
+      return list.build();
+    }
+  }
