+        if (x.length() == ncy) {     /* x as row vector */
+          nrx = 1;
+          ncx = ncy; /* == x.length() */
+        }
+        else if (ncy == 1) {        /* x as col vector */
+          nrx = x.length();
+          ncx = 1;
+        }
+      }
+    }
