+
+  @Override
+  public void addStatement(TacFactory tacFactory, FunctionCall call) {
+    if(call.getArguments() != Null.INSTANCE) {
+      for(SEXP arg : call.getArguments().values()) {
+        tacFactory.addStatement(arg);
