+        int group = ugroup.indexOf(groups, row, 0);
+        groupSums[group] += source.getElementAsDouble(row, col);
+      }
+
+      // copy sums to matrix
+      for(int group=0;group!=ugroup.length();++group) {
+        result.setValue(group, col, groupSums[group]);
+      }
+
+    }
+    return result.build();
