+      if(node.hasTag()) {
+        if(node.getTag().getPrintName().startsWith(symbol.getPrintName()))
{
+          match = node.getValue();
+          matchCount++;
+        }
+      }
+    }
+    return matchCount == 1 ? match : Null.INSTANCE;
+  }
+
+  @Generic @Primitive("$")
+  public static SEXP getElementByName(Environment env, @Evaluate(false)
