+            result.setNA(0);
+            return result.build();
+          }
+        }
+      }
+    }
+
+    // handle the more complicated cases
+    return new SubscriptOperation()
+        .setSource(source)
+        .setDrop(drop)
+        .setSubscripts(arguments)
+        .extract();
+  }
