-  private SEXP tryDispatchGeneric(Context context, Environment rho, String
name, FunctionCall call,
-                                        List<JvmMethod> overloads,
List<ProvidedArgument> provided) {
-    // check first to see if this method should be executed generically.
-    if(!isGeneric(overloads)) {
-      return null;
-    }
-
-    if(overloads.get(0).isGroupGeneric()) {
-
-      PairList evaluated = Calls.evaluateList(context, rho,
call.getArguments());
-
-      SEXP dispatched = Calls.DispatchGroup("Ops",call, name, evaluated,
context, rho);
-      if(dispatched != null) {
-        return dispatched;
-      }
-
-    }
-
-    if(call.getFunction() instanceof Symbol) {
-      if(((Symbol)
call.getFunction()).getPrintName().endsWith(".default")) {
-        return null;
-      }
-    }
-    if(provided.isEmpty()) {
-      throw new EvalException("hmm generic primitive with zero args: " +
overloads.toString());
-    }
-
-    Vector classes =
(Vector)provided.get(0).evaluated().getAttribute(Symbols.CLASS);
-    if(classes.length() == 0) {
-      return null;
-    }
-
-    DispatchChain chain = DispatchChain.newChain(rho,
overloads.get(0).getGenericName(), classes);
-    if(chain == null) {
-      return null;
-    }
-
-    // Repromise ?
-    PairList.Node restOfArguments = (PairList.Node) call.getArguments();
-    PairList newArgs = new PairList.Node(new
Promise(provided.get(0).provided, provided.get(0).evaluated()),
-        restOfArguments.hasNextNode() ? restOfArguments.getNextNode() :
Null.INSTANCE);
-
-    FunctionCall newCall = FunctionCall.newCall(chain.getMethodSymbol(),
newArgs);
-
-    ClosureDispatcher dispatcher = new ClosureDispatcher(context, rho,
newCall);
-    return dispatcher.apply(chain, newArgs);
-  }
