-        isGeneric = true;
-      } else {
-        isNotGeneric = true;
-      }
-    }
-    if(isGeneric && isNotGeneric) {
-      throw new EvalException("all overloads must be marked with @Generic
/ @GroupGeneric or none: " + overloads.toString());
-    }
-
-    return isGeneric;
-  }
