-  private int countCycles(JvmMethod method, SEXP[] arguments) {
-    int maxLength = 0;
-    for(int i=0;i!=arguments.length;++i) {
-      if(method.getFormals().get(i).isRecycle()) {
-        if(arguments[i].length() == 0) {
-          return 0;
-        }
-        maxLength = Math.max(maxLength, arguments[i].length());
-      }
-    }
-    return maxLength;
-  }
