-  private boolean convertArguments(JvmMethod method, SEXP[] preparedArgs,
Object[] args, int cycle) {
-    for(int i=0;i!=preparedArgs.length;++i) {
-      JvmMethod.Argument formal = method.getFormals().get(i);
-      if(formal.isRecycle()) {
-        AtomicAccessor vector = AtomicAccessors.create(preparedArgs[i],
formal.getClazz());
-        int vectorIndex = cycle % vector.length();
-        if(vector.isNA(vectorIndex) && !method.acceptsNA()) {
-          return false;
-        }
-        args[i] = vector.get(vectorIndex);
-      } else {
-        args[i] = getConverter(preparedArgs[i],
formal).convert(preparedArgs[i], formal);
-      }
-    }
-    return true;
-  }
